// ===========================================================================
//  BỘ NÃO BOT - đọc lệnh anh nhắn, tính, trả kết quả. Sửa 2 dòng dưới nếu cần.
// ===========================================================================
const OWNER = 5239928968;   // chỉ Chat ID này mới dùng được bot (chống người lạ)
const NAV   = 5000000;      // tài sản ròng (ĐỒNG) - sửa khi anh nạp thêm vốn
const MAX_POS_PCT = 100;    // trần % NAV / 1 vị thế
// ===========================================================================

const upd = $input.first().json;
const msg = upd.message || upd.channel_post || {};
const text = (msg.text || '').trim();
const chatId = msg.chat && msg.chat.id;
const out = (m) => [{ json: { chatId, message: m } }];

if (String(chatId) !== String(OWNER)) return out('⛔ Bot riêng tư.');

const help = '🤖 *Lệnh bot CK*\n\n'
  + '🧮 `/size MÃ vào cắtlỗ [mụctiêu] [risk%]`\n   _vd: /size BID 42 39 46_ — tính khối lượng & R:R\n\n'
  + '🧭 `/check MÃ vào cắtlỗ [mụctiêu]`\n   _vd: /check FPT 75 69 88_ — bảng 7 câu (định giá + dòng tiền)\n\n'
  + '_Giá nhập theo NGHÌN đồng (42 = 42.000đ). /help xem lại._';

if (!text || /^\/(start|help)\b/i.test(text)) return out(help);

const parts = text.split(/\s+/);
const cmd = parts[0].toLowerCase().replace(/@.*$/, '');
const TICKER = (parts[1] || '').toUpperCase();
const ENTRY = parseFloat(parts[2]);
const STOP  = parseFloat(parts[3]);
const TARGET = parts[4] != null ? parseFloat(parts[4]) : 0;
const RISK_PCT = parts[5] != null ? parseFloat(parts[5]) : 1.5;

const fmtM = (d) => (d / 1e6).toFixed(d < 1e7 ? 2 : 1) + ' triệu';
const fmtP = (k) => Math.round(k * 1000).toLocaleString('vi-VN') + 'đ';

const sizing = () => {
  const entryD = ENTRY * 1000, riskBudget = NAV * RISK_PCT / 100, riskPerShare = (ENTRY - STOP) * 1000, lotCost = entryD * 100;
  const byRisk = Math.floor(riskBudget / riskPerShare / 100) * 100;
  const byCap = Math.floor(NAV * MAX_POS_PCT / 100 / entryD / 100) * 100;
  const shares = Math.max(0, Math.min(byRisk, byCap));
  const rr = TARGET > ENTRY ? (TARGET - ENTRY) / (ENTRY - STOP) : null;
  const L = ['🧮 *SIZING — ' + TICKER + '*', '_Vào ' + fmtP(ENTRY) + ' · Cắt lỗ ' + fmtP(STOP) + (TARGET > 0 ? ' · MT ' + fmtP(TARGET) : '') + ' · NAV ' + fmtM(NAV) + '_', ''];
  if (shares <= 0) {
    L.push('→ Quy tắc rủi ro ' + RISK_PCT + '%: chưa nên mua (< 1 lô).');
    L.push(lotCost <= NAV ? '⚠️ Mua tối thiểu 1 lô = ' + fmtM(lotCost) + ' (' + (lotCost / NAV * 100).toFixed(0) + '% NAV → tập trung cao).' : '🔴 NAV không đủ 1 lô (' + fmtM(lotCost) + ').');
  } else {
    L.push('→ *MUA ' + shares.toLocaleString('vi-VN') + ' cp* (' + (shares / 100) + ' lô) = ' + fmtM(shares * entryD) + ' (' + (shares * entryD / NAV * 100).toFixed(0) + '% NAV)');
    L.push('→ Rủi ro thực: *' + fmtM(shares * riskPerShare) + '* (' + (shares * riskPerShare / NAV * 100).toFixed(2) + '% NAV)');
  }
  if (rr != null) L.push('→ *R:R ' + rr.toFixed(2) + '*' + (rr < 2 ? ' ⚠️ mỏng (<2)' : ' ✓'));
  return L.join('\n');
};

if (cmd === '/size') {
  if (!TICKER || !(ENTRY > 0) || !(STOP > 0)) return out('⚠️ Cú pháp: `/size MÃ vào cắtlỗ [mụctiêu] [risk%]`\nVd: /size BID 42 39 46');
  if (!(STOP < ENTRY)) return out('⚠️ Cắt lỗ phải THẤP HƠN giá vào.');
  return out(sizing());
}

if (cmd === '/check') {
  if (!TICKER || !(ENTRY > 0) || !(STOP > 0)) return out('⚠️ Cú pháp: `/check MÃ vào cắtlỗ [mụctiêu]`\nVd: /check FPT 75 69 88');
  const hFin = { 'User-Agent': 'Mozilla/5.0', 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };
  // định giá
  let q2 = '_thiếu P/E_';
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:' + TICKER + '~itemCode:51006,1000043&sort=reportDate:desc&size=8', headers: hFin, json: false, timeout: 12000 });
    let p; try { p = typeof r === 'string' ? JSON.parse(r) : r; } catch (e) { p = null; }
    const m = {}; for (const d of ((p && p.data) || [])) if (!(d.ratioCode in m)) m[d.ratioCode] = d.value;
    const pe = m.PRICE_TO_EARNINGS, pe5 = m.PRICE_TO_EARNINGS_AVG_CR_5Y;
    if (pe > 0 && pe5 > 0) { const k = pe / pe5; q2 = 'P/E ' + pe.toFixed(1) + ' vs TB5N ' + pe5.toFixed(1) + ' → ' + (k <= 0.85 ? '🟢 RẺ so lịch sử' : k >= 1.15 ? '🔴 ĐẮT so lịch sử' : '🟡 quanh TB'); }
    else if (pe > 0) q2 = 'P/E ' + pe.toFixed(1);
  } catch (e) { q2 = '_lỗi lấy P/E_'; }
  // dòng tiền
  let q4 = '_thiếu_';
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + TICKER + '&size=5&sort=tradingDate:desc', headers: hFin, json: true, timeout: 12000 });
    const nets = ((r && r.data) || []).map(x => (x.netVal || 0) / 1e9);
    if (nets.length) { const dir = nets[0] > 1 ? 1 : nets[0] < -1 ? -1 : 0; let st = 0; for (const v of nets) { const s = v > 1 ? 1 : v < -1 ? -1 : 0; if (s === dir && dir) st++; else break; } q4 = 'phiên gần nhất ' + nets[0].toFixed(1) + ' tỷ' + (st >= 2 ? ' · ' + (dir > 0 ? 'GOM' : 'XẢ') + ' ' + st + ' phiên' : '') + ' · tổng 5p ' + nets.reduce((a, b) => a + b, 0).toFixed(1) + ' tỷ'; }
  } catch (e) { q4 = '_lỗi_'; }
  // sizing tóm tắt cho câu 6
  const rr = TARGET > ENTRY ? (TARGET - ENTRY) / (ENTRY - STOP) : null;
  const entryD = ENTRY * 1000, byRisk = Math.floor(NAV * RISK_PCT / 100 / ((ENTRY - STOP) * 1000) / 100) * 100, lot = entryD * 100;
  const q6 = (byRisk >= 100 ? 'mua ' + byRisk + ' cp theo rủi ro ' + RISK_PCT + '%' : (lot <= NAV ? '⚠️ chỉ đủ ~1 lô (' + (lot / NAV * 100).toFixed(0) + '% NAV)' : '🔴 NAV không đủ 1 lô')) + ' · R:R ' + (rr ? rr.toFixed(2) + (rr < 2 ? ' ⚠️' : '') : 'n/a');
  const L = ['🧭 *BẢNG 7 CÂU — ' + TICKER + '*', '_Vào ' + fmtP(ENTRY) + ' · CL ' + fmtP(STOP) + (TARGET ? ' · MT ' + fmtP(TARGET) : '') + '_', ''];
  L.push('① Hiểu DN? _(tự trả lời)_');
  L.push('② Rẻ/đắt? ✅ ' + q2);
  L.push('③ Luận điểm & điều gì làm sai? _(tự viết)_');
  L.push('④ Bối cảnh? ✅ KN: ' + q4);
  L.push('⑤ Thời điểm? _(xúc tác hay bắt dao?)_');
  L.push('⑥ Kích thước & R:R? ✅ ' + q6);
  L.push('⑦ Thoát? ✅ CL ' + fmtP(STOP) + (TARGET ? ' · MT ' + fmtP(TARGET) : ' · _chưa đặt MT_'));
  L.push('');
  L.push('📝 Phải tự trả lời ①③⑤. Không trọn 7 câu → ĐỨNG NGOÀI.');
  return out(L.join('\n'));
}

return out('❓ Lệnh không hiểu.\n\n' + help);
